// Generated by vibelang from src/features/personal-model/queries.ts; the migrate flow writes it again with each batch.
import { LiveQuery } from "@smthrs/effect-tanstack-db";
// What every frontend reads of a person's own models (docs/features/personal-model.md#the-settings-section). Each is a
// live query over this device's collections; none waits for the network, and none can carry a key: no collection holds
// one.
/**
 * The person's connections, in their order: each one's kind, whether it is active, its base URL, the models its tiers
 * name, its credential's last characters and its last failure; none when nothing is saved.
 */
export const rowsQuery = (rows) => LiveQuery.make((q) => q.from({ model: rows.tanstack }).orderBy(({ model }) => model.position));
/** The form's last write on this tab. */
export const formQuery = (form) => LiveQuery.make((q) => q.from({ form: form.tanstack }).findOne());
/** The last test on this tab. */
export const testQuery = (test) => LiveQuery.make((q) => q.from({ test: test.tanstack }).findOne());
/** Which of Add's menu and forms shows on this tab. */
export const addQuery = (add) => LiveQuery.make((q) => q.from({ add: add.tanstack }).findOne());
/** The last Codex link on this tab. */
export const linkQuery = (link) => LiveQuery.make((q) => q.from({ link: link.tanstack }).findOne());
